// 2. Tagged Template Example (Sanitize HTML)
function sanitize(strings, ...values) {
  return strings.reduce((acc, str, i) => {
    const val = String(values[i - 1] ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;');
    return acc + val + str;
  });
}

