// 1. Promise Chain (Khó đọc khi có nhiều phụ thuộc)
function getUserDataOld(userId) {
  return fetchUser(userId)
    .then(user => fetchPosts(user.id).then(posts => ({ user, posts })))
    .catch(err => console.error(err));
}

// 2. async/await (Tuần tự, dễ đọc, clean scope)
async function getUserDataModern(userId) {
  try {
    const user = await fetchUser(userId);
    const posts = await fetchPosts(user.id); // Dễ dàng dùng biến 'user' ở đây
    return { user, posts };
  } catch (err) {
    console.error('Lỗi khi lấy thông tin:', err.message);
    throw err;
  }
}

