const items = [1, 2, 3];
const save = async (x) => {
  await new Promise(r => setTimeout(r, 10));
  console.log('Saved:', x);
};

// ❌ SAI: forEach không chờ
async function badExample() {
  items.forEach(async (item) => {
    await save(item);
  });
  console.log('Done bad!'); // In ra ĐẦU TIÊN trước khi save xong!
}

//  ĐÚNG Cách 1: Tuần tự từng cái một (Sequential)
async function goodSequential() {
  for (const item of items) {
    await save(item);
  }
  console.log('Done sequential!');
}

//  ĐÚNG Cách 2: Chạy song song tất cả cùng lúc (Parallel)
async function goodParallel() {
  await Promise.all(items.map(item => save(item)));
  console.log('Done parallel!');
}

