//  ĐÚNG Cách 2: Chuyển thành Promise (Idiomatic)
const delayFail = () => new Promise((_, reject) => {
  setTimeout(() => reject(new Error('Promise rejected from timer')), 10);
});

async function handleTimer() {
  try {
    await delayFail();
  } catch (err) {
    console.log('Bắt lỗi thành công với async/await:', err.message);
  }
}

