async function dispatchActionWithOfflineSupport(action) {
  if (!navigator.onLine) {
    await saveToOfflineQueue(action);
    return { status: 'queued' };
  }
  try {
    return await sendToServer(action);
  } catch (err) {
    await saveToOfflineQueue(action);
    return { status: 'queued' };
  }
}

