function createBankAccount(initialBalance) {
  // 'balance' là private variable, bên ngoài không thể can thiệp trực tiếp
  let balance = initialBalance;

  return {
    deposit(amount) {
      if (amount <= 0) throw new Error('Số tiền không hợp lệ');
      balance += amount;
      return balance;
    },
    withdraw(amount) {
      if (amount > balance) throw new Error('Số dư không đủ');
      balance -= amount;
      return balance;
