function throttle(fn, limit = 200) {
  let lastRun = 0;
  let timeoutId = null;
  let lastArgs = null;
  let lastContext = null;

  return function(...args) {
    const now = Date.now();
    const remaining = limit - (now - lastRun);
    lastArgs = args;
    lastContext = this;

    if (remaining <= 0 || remaining > limit) {
      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }
      lastRun = now;
      fn.apply(lastContext, lastArgs);
    } else if (!timeoutId) {
      // Đảm bảo chạy trailing call cuối cùng
      timeoutId = setTimeout(() => {
        lastRun = Date.now();
        timeoutId = null;
        fn.apply(lastContext, lastArgs);
      }, remaining);
    }
  };
}

