function deepClone(obj, hash = new WeakMap()) {
  // 1. Xử lý primitive values và null
  if (Object(obj) !== obj || typeof obj === 'function') return obj;

  // 2. Xử lý Circular References
  if (hash.has(obj)) return hash.get(obj);

  // 3. Xử lý các kiểu dữ liệu đặc biệt
  if (obj instanceof Date) return new Date(obj);
  if (obj instanceof RegExp) return new RegExp(obj.source, obj.flags);
  if (obj instanceof Map) {
    const mapCopy = new Map();
    hash.set(obj, mapCopy);
    obj.forEach((val, key) => mapCopy.set(deepClone(key, hash), deepClone(val, hash)));
    return mapCopy;
  }
  if (obj instanceof Set) {
    const setCopy = new Set();
    hash.set(obj, setCopy);
    obj.forEach(val => setCopy.add(deepClone(val, hash)));
    return setCopy;
  }

  // 4. Tạo bản sao kế thừa đúng prototype (Array hoặc Object)
  const clone = Array.isArray(obj) ? [] : Object.create(Object.getPrototypeOf(obj));
  hash.set(obj, clone);

  // 5. Duyệt cả string keys lẫn Symbol keys
  Reflect.ownKeys(obj).forEach(key => {
    clone[key] = deepClone(obj[key], hash);
  });

  return clone;
}

// Cách 1: Đệ quy có kiểm soát độ sâu (depth) tối ưu O(N)
function flattenRecursive(arr, depth = 1) {
  if (depth <= 0) return arr.slice();
  const result = [];
  for (const item of arr) {
    if (Array.isArray(item)) {
      result.push(...flattenRecursive(item, depth - 1));
    } else {
      result.push(item);
    }
  }
  return result;
}

// Cách 2: Khử đệ quy bằng Stack (An toàn tuyệt đối cho mảng lồng sâu vô tận)
function flattenIterative(arr) {
  const stack = [...arr];
  const res = [];
  while (stack.length) {
    const next = stack.pop();
    if (Array.isArray(next)) {
      stack.push(...next); // Đẩy các phần tử con trở lại stack
    } else {
      res.push(next);
    }
  }
  return res.reverse(); // Đảo ngược để giữ đúng thứ tự ban đầu
}

console.log(flattenRecursive([1, [2, [3, [4]]]], 2)); // [1, 2, 3, [4]]
console.log(flattenIterative([1, [2, [3, [4]]]]));     // [1, 2, 3, 4]

function promiseAll(iterable) {
  return new Promise((resolve, reject) => {
    const promises = Array.from(iterable); // Chuyển iterable thành array
    const total = promises.length;

    if (total === 0) return resolve([]); // Mảng rỗng resolve ngay

    const results = new Array(total);
    let completedCount = 0;

    promises.forEach((promiseItem, index) => {
      // Bọc Promise.resolve để xử lý cả giá trị non-promise
      Promise.resolve(promiseItem)
        .then(value => {
          results[index] = value; // Bảo toàn đúng index ban đầu
          completedCount++;
          if (completedCount === total) {
            resolve(results);
          }
        })
        .catch(reject); // Fail-fast: Gặp lỗi là reject ngay lập tức
    });
  });
}

import { useState, useEffect, useCallback } from 'react';

export function useLocalStorage(key, initialValue) {
  // 1. Lazy initializer an toàn SSR
  const [storedValue, setStoredValue] = useState(() => {
    if (typeof window === 'undefined') return initialValue;
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.warn(`Lỗi đọc localStorage key "${key}":`, error);
      return initialValue;
    }
  });

  // 2. Hàm setter hỗ trợ updater function
  const setValue = useCallback((value) => {
    try {
      const valueToStore = value instanceof Function ? value(storedValue) : value;
      setStoredValue(valueToStore);
      if (typeof window !== 'undefined') {
        window.localStorage.setItem(key, JSON.stringify(valueToStore));
      }
    } catch (error) {
      console.error(`Lỗi ghi localStorage key "${key}":`, error);
    }
  }, [key, storedValue]);

  // 3. Đồng bộ giữa các tab khác nhau
  useEffect(() => {
    const handleStorageChange = (e) => {
      if (e.key === key && e.newValue) {
        try { setStoredValue(JSON.parse(e.newValue)); } catch {}
      }
    };
    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, [key]);

  return [storedValue, setValue];
}

import { useEffect, useRef, useCallback } from 'react';

export function useInfiniteScroll({ onLoadMore, hasMore, isLoading, rootMargin = '300px' }) {
  const sentinelRef = useRef(null);

  const handleObserver = useCallback((entries) => {
    const [target] = entries;
    if (target.isIntersecting && hasMore && !isLoading) {
      onLoadMore();
    }
  }, [onLoadMore, hasMore, isLoading]);

  useEffect(() => {
    const element = sentinelRef.current;
    if (!element) return;

    const observer = new IntersectionObserver(handleObserver, {
      root: null,
      rootMargin, // Tải trước 300px trước khi user cuộn chạm đáy
      threshold: 0
    });

    observer.observe(element);
    return () => observer.disconnect(); // Dọn dẹp observer
  }, [handleObserver, rootMargin]);

  return sentinelRef;
}

