async function retryWithBackoff(fn, options = {}) {
  const {
    maxRetries = 4,
    baseDelay = 1000, // 1s
    maxDelay = 10000, // 10s
    shouldRetry = (err) => true // Điều kiện lọc lỗi
  } = options;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      if (attempt === maxRetries || !shouldRetry(error)) {
        throw error; // Hết số lần thử hoặc lỗi không thể retry
      }

      // Tính thời gian chờ exponential + Full Jitter ngẫu nhiên
      const expDelay = Math.min(maxDelay, baseDelay * (2 ** attempt));
      const jitter = Math.random() * (expDelay * 0.3);
      const totalDelay = expDelay + jitter;

      console.warn(`Lần thử ${attempt + 1} thất bại. Đang chờ ${totalDelay.toFixed(0)}ms...`);
      await new Promise(r => setTimeout(r, totalDelay));
    }
  }
}

function deepEqual(a, b) {
  // 1. Primitive và cùng tham chiếu
  if (Object.is(a, b)) return true;

  // 2. Nếu một trong hai là primitive hoặc null
  if (a === null || typeof a !== 'object' || b === null || typeof b !== 'object') {
    return false;
  }

  // 3. Khác Constructor (ví dụ Array vs Object thường)
  if (a.constructor !== b.constructor) return false;

  // 4. Xử lý Date & RegExp
  if (a instanceof Date) return a.getTime() === b.getTime();
  if (a instanceof RegExp) return a.toString() === b.toString();

  // 5. So sánh số lượng keys
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;

  // 6. Đệ quy so sánh từng thuộc tính
  for (const key of keysA) {
    if (!Object.hasOwn(b, key)) return false;
    if (!deepEqual(a[key], b[key])) return false;
  }

  return true;
}

function memoize(fn, resolver) {
  const cache = new Map();

  function memoized(...args) {
    // Tạo cache key từ đối số
    const key = resolver ? resolver(...args) : JSON.stringify(args);

    if (cache.has(key)) {
      return cache.get(key); // Lấy từ cache O(1)
    }

    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  }

  // Cung cấp method xóa cache nếu cần
  memoized.cache = cache;
  return memoized;
}

