// Giải pháp Senior: Rule-based, tuân thủ Open-Closed Principle
function fizzBuzzExtensible(n, customRules = [[3, 'Fizz'], [5, 'Buzz']]) {
  const results = [];

  for (let i = 1; i <= n; i++) {
    let str = '';
    for (const [divisor, word] of customRules) {
      if (i % divisor === 0) {
        str += word;
      }
    }
    results.push(str || i);
  }

  return results;
}

